<?php
declare(strict_types=1);

/**
 * install_payouts_first_pass_v001_20261029_015249am.php
 *
 * VERSION: v001
 * LAST MODIFIED: 10/29/2026 1:52:49 am ET
 *
 * PURPOSE:
 * - Install first-pass MRL Payouts system into /race_results.
 * - Adds payouts.php, admin_payouts.php, payouts_helper.php, and initial payout config.
 * - Does not modify weekly_standings.php, database schema/data, scheduler, cron, email, or picks.
 * - Existing payout config is NEVER overwritten if it differs from the installer seed.
 *
 * REPORT UX:
 * - Compact PRECHECK / POSTCHECK JSON boxes with Copy buttons.
 * - Download JSON remains available as an optional secondary action.
 *
 * PHP: 7.3 compatible.
 */

date_default_timezone_set('America/New_York');
if (session_status() === PHP_SESSION_NONE) session_start();

require_once __DIR__ . '/config.php';
require_once __DIR__ . '/config_mrl.php';
require_once __DIR__ . '/class.user.php';

$user_home = new USER();
if (!$user_home->is_logged_in()) {
    $user_home->redirect('/login.php');
    exit;
}
if (!function_exists('isAdmin') || !isAdmin((int)($_SESSION['userSession'] ?? 0))) {
    http_response_code(403);
    exit('Admin access required.');
}

const MRLP_INSTALLER_VERSION = 'v001';
const MRLP_INSTALLER_PAYLOAD_B64 = '';

function mrpi_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }

function mrpi_payload(): array
{
    $json = base64_decode(MRLP_INSTALLER_PAYLOAD_B64, true);
    if (!is_string($json)) throw new RuntimeException('Embedded payload decode failed.');
    $data = json_decode($json, true);
    if (!is_array($data)) throw new RuntimeException('Embedded payload JSON is invalid.');
    return $data;
}

function mrpi_target_path(string $rel): string
{
    return __DIR__ . '/' . ltrim($rel, '/');
}

function mrpi_lint(string $file): array
{
    if (!function_exists('shell_exec')) {
        return ['ok'=>false,'output'=>'shell_exec() is not available. Check Hostinger PHP Configuration -> disableFunctions.'];
    }
    $out = shell_exec('php -l ' . escapeshellarg($file) . ' 2>&1');
    $text = trim((string)$out);
    return ['ok'=>($text !== '' && strpos($text, 'No syntax errors detected') !== false),'output'=>$text];
}

function mrpi_stage_candidate(string $rel, array $meta): array
{
    $raw = base64_decode((string)($meta['b64'] ?? ''), true);
    if (!is_string($raw)) return ['ok'=>false,'path'=>'','sha256'=>'','lint'=>['ok'=>false,'output'=>'Candidate decode failed.']];
    $sha = hash('sha256', $raw);
    if ($sha !== (string)($meta['sha256'] ?? '')) return ['ok'=>false,'path'=>'','sha256'=>$sha,'lint'=>['ok'=>false,'output'=>'Candidate SHA-256 mismatch.']];
    if (empty($meta['is_php'])) return ['ok'=>true,'path'=>'','sha256'=>$sha,'lint'=>['ok'=>true,'output'=>'Not a PHP target.']];
    $tmp = tempnam(sys_get_temp_dir(), 'mrlp_');
    if (!$tmp) return ['ok'=>false,'path'=>'','sha256'=>$sha,'lint'=>['ok'=>false,'output'=>'Could not create temp file.']];
    if (file_put_contents($tmp, $raw, LOCK_EX) === false) {
        @unlink($tmp);
        return ['ok'=>false,'path'=>'','sha256'=>$sha,'lint'=>['ok'=>false,'output'=>'Could not stage temp file.']];
    }
    $lint = mrpi_lint($tmp);
    return ['ok'=>(bool)$lint['ok'],'path'=>$tmp,'sha256'=>$sha,'lint'=>$lint];
}

function mrpi_required_dependencies(): array
{
    return [
        'config.php',
        'config_mrl.php',
        'class.user.php',
        'mrl_team/mrl_theme_helper.php',
        'mrl_team/mrl_shared_theme.css',
        'race_results/race_results_team_helper.php',
        'race_results/race_results_snapshot_helper.php',
        'race_results/race_results_engine.php',
        'race_results/race_schedule_helper.php',
    ];
}

function mrpi_preflight(): array
{
    $payload = mrpi_payload();
    $checks = [];
    $files = [];

    $shell = function_exists('shell_exec');
    $checks[] = ['label'=>'shell_exec available for Hostinger php -l','status'=>$shell?'PASS':'FAIL','required'=>true,'detail'=>$shell?'Available.':'Unavailable; check Hostinger disableFunctions.'];

    foreach (mrpi_required_dependencies() as $rel) {
        $path = mrpi_target_path($rel);
        $ok = is_file($path);
        $checks[] = ['label'=>'Dependency exists: '.$rel,'status'=>$ok?'PASS':'FAIL','required'=>true,'detail'=>$path];
    }

    foreach ($payload as $rel => $meta) {
        $path = mrpi_target_path((string)$rel);
        $exists = is_file($path);
        $dir = dirname($path);
        $dirReady = is_dir($dir) ? is_writable($dir) : is_writable(dirname($dir));
        $checks[] = ['label'=>'Target folder writable: '.$rel,'status'=>$dirReady?'PASS':'FAIL','required'=>true,'detail'=>$dir];

        $candidate = mrpi_stage_candidate((string)$rel, (array)$meta);
        $checks[] = ['label'=>'Candidate SHA-256: '.$rel,'status'=>($candidate['sha256']===(string)$meta['sha256'])?'PASS':'FAIL','required'=>true,'detail'=>(string)$candidate['sha256']];
        if (!empty($meta['is_php'])) {
            $checks[] = ['label'=>'Candidate php -l: '.$rel,'status'=>!empty($candidate['lint']['ok'])?'PASS':'FAIL','required'=>true,'detail'=>(string)$candidate['lint']['output']];
        }
        if (!empty($candidate['path'])) @unlink((string)$candidate['path']);

        $existingSha = $exists ? hash_file('sha256', $path) : '';
        $configConflict = !empty($meta['is_config']) && $exists && $existingSha !== (string)$meta['sha256'];
        if (!empty($meta['is_config'])) {
            $checks[] = [
                'label'=>'Payout config safe to seed',
                'status'=>$configConflict?'FAIL':'PASS',
                'required'=>true,
                'detail'=>$configConflict
                    ? 'Existing payout config differs from installer seed. Apply is blocked so admin settings cannot be overwritten.'
                    : ($exists ? 'Existing config already matches seed; it will be preserved.' : 'No existing config; seed will be created.'),
            ];
        }

        $files[$rel] = [
            'path'=>$path,
            'exists_before'=>$exists,
            'sha256_before'=>$existingSha,
            'candidate_sha256'=>(string)$meta['sha256'],
            'action'=>(!empty($meta['is_config']) ? ($exists?'preserve':'create') : ($exists?'replace':'create')),
        ];
    }

    $ok = true;
    foreach ($checks as $c) if (!empty($c['required']) && $c['status'] !== 'PASS') $ok = false;

    return [
        'installer'=>'install_payouts_first_pass',
        'installer_version'=>MRLP_INSTALLER_VERSION,
        'report_stage'=>'PRECHECK',
        'report_generated_et'=>date('c'),
        'scope'=>[
            'adds'=>['race_results/payouts_helper.php','race_results/payouts.php','race_results/admin_payouts.php','race_results/_payouts/payouts_config.json'],
            'does_not_change'=>['weekly_standings.php','database schema/data','cron/scheduler','email','pick submissions'],
            'config_safety'=>'Existing modified payout config blocks Apply and is never overwritten.',
        ],
        'result'=>['ok'=>$ok,'checks'=>$checks,'files'=>$files],
        'last_installer_session'=>$_SESSION['mrpi_last'] ?? [],
    ];
}

function mrpi_backup_targets(array $payload): array
{
    $root = __DIR__ . '/_installer_backups/install_payouts_first_pass_v001_' . date('Ymd_hisA');
    $items = [];
    $any = false;
    foreach ($payload as $rel => $meta) {
        $path = mrpi_target_path((string)$rel);
        if (!is_file($path)) continue;
        $any = true;
        $backup = $root . '/' . (string)$rel;
        if (!is_dir(dirname($backup)) && !mkdir(dirname($backup), 0755, true) && !is_dir(dirname($backup))) {
            throw new RuntimeException('Could not create backup folder for '.$rel);
        }
        if (!copy($path, $backup)) throw new RuntimeException('Could not back up '.$rel);
        $src = hash_file('sha256', $path); $bak = hash_file('sha256', $backup);
        if ($src !== $bak) throw new RuntimeException('Backup hash mismatch for '.$rel);
        $items[$rel] = ['source'=>$path,'backup'=>$backup,'sha256_source'=>$src,'sha256_backup'=>$bak];
    }
    return ['backup_root'=>$any?$root:'','files'=>$items];
}

function mrpi_write_atomic(string $path, string $raw): void
{
    $dir = dirname($path);
    if (!is_dir($dir) && !mkdir($dir, 0755, true) && !is_dir($dir)) throw new RuntimeException('Could not create target directory: '.$dir);
    $tmp = $path . '.mrlnew_' . bin2hex(random_bytes(4));
    if (file_put_contents($tmp, $raw, LOCK_EX) === false) throw new RuntimeException('Could not stage '.$path);
    @chmod($tmp, 0644);
    if (!@rename($tmp, $path)) { @unlink($tmp); throw new RuntimeException('Could not install '.$path); }
    @chmod($path, 0644);
}

function mrpi_postcheck(array $session): array
{
    $payload = mrpi_payload();
    $checks = [];
    $files = [];
    foreach ($payload as $rel => $meta) {
        $path = mrpi_target_path((string)$rel);
        $exists = is_file($path);
        $checks[] = ['label'=>'Installed target exists: '.$rel,'status'=>$exists?'PASS':'FAIL','required'=>true,'detail'=>$path];
        $sha = $exists ? hash_file('sha256', $path) : '';
        $shaOk = ($sha === (string)$meta['sha256']);
        $checks[] = ['label'=>'Installed SHA-256: '.$rel,'status'=>$shaOk?'PASS':'FAIL','required'=>true,'detail'=>$sha];
        $lint = ['ok'=>true,'output'=>'Not a PHP target.'];
        if (!empty($meta['is_php'])) {
            $lint = $exists ? mrpi_lint($path) : ['ok'=>false,'output'=>'Target missing.'];
            $checks[] = ['label'=>'Installed php -l: '.$rel,'status'=>!empty($lint['ok'])?'PASS':'FAIL','required'=>true,'detail'=>(string)$lint['output']];
        }
        if (!empty($meta['is_config']) && $exists) {
            $raw = @file_get_contents($path);
            $decoded = is_string($raw) ? json_decode($raw, true) : null;
            $jsonOk = is_array($decoded) && isset($decoded['years']['2026']);
            $checks[] = ['label'=>'Installed payout config JSON valid','status'=>$jsonOk?'PASS':'FAIL','required'=>true,'detail'=>$jsonOk?'Valid JSON with 2026 defaults.':'Invalid/missing required 2026 defaults.'];
        }
        $files[$rel] = ['path'=>$path,'sha256_after'=>$sha,'expected_sha256'=>(string)$meta['sha256'],'lint'=>$lint];
    }
    $ok = true; foreach ($checks as $c) if (!empty($c['required']) && $c['status'] !== 'PASS') $ok = false;
    return [
        'installer'=>'install_payouts_first_pass',
        'installer_version'=>MRLP_INSTALLER_VERSION,
        'report_stage'=>'POSTCHECK',
        'report_generated_et'=>date('c'),
        'result'=>['ok'=>$ok,'checks'=>$checks,'files'=>$files],
        'last_installer_session'=>$session,
    ];
}

function mrpi_restore_backup(array $backupInfo): array
{
    $ok = true; $restored=[];
    foreach (($backupInfo['files'] ?? []) as $rel => $row) {
        $src=(string)($row['backup']??'');$dst=(string)($row['source']??'');
        if ($src==='' || $dst==='' || !is_file($src) || !copy($src,$dst)) {$ok=false;$restored[$rel]=false;} else {$restored[$rel]=(hash_file('sha256',$dst)===(string)($row['sha256_backup']??''));if(!$restored[$rel])$ok=false;}
    }
    return ['ok'=>$ok,'files'=>$restored];
}

if (!isset($_SESSION['mrpi_csrf'])) $_SESSION['mrpi_csrf']=bin2hex(random_bytes(24));
$message='';$messageClass='info';

if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=(string)($_POST['action']??'');
    if (!hash_equals((string)$_SESSION['mrpi_csrf'],(string)($_POST['csrf']??''))) {
        $message='Security token mismatch.';$messageClass='bad';
    } elseif ($action==='apply') {
        $pre=mrpi_preflight();
        if (empty($pre['result']['ok'])) {$message='Apply blocked: preflight is not fully green.';$messageClass='bad';}
        else {
            $payload=mrpi_payload();$backup=[];$created=[];
            try {
                $backup=mrpi_backup_targets($payload);
                foreach($payload as $rel=>$meta){
                    $path=mrpi_target_path((string)$rel);
                    if (!empty($meta['is_config']) && is_file($path)) continue;
                    $raw=base64_decode((string)$meta['b64'],true);if(!is_string($raw))throw new RuntimeException('Decode failed: '.$rel);
                    if(hash('sha256',$raw)!==(string)$meta['sha256'])throw new RuntimeException('SHA mismatch: '.$rel);
                    $wasThere=is_file($path);mrpi_write_atomic($path,$raw);if(!$wasThere)$created[]=$path;
                }
                $session=['last_action'=>'apply','at_et'=>date('c'),'ok'=>true,'message'=>'Apply completed; running postflight.','backup'=>$backup,'created_files'=>$created,'automatic_rollback'=>null];
                $post=mrpi_postcheck($session);
                if(empty($post['result']['ok'])){
                    $restore=mrpi_restore_backup($backup);foreach($created as $p){if(is_file($p) && !isset(($backup['files']??[])[str_replace(__DIR__.'/','',$p)]))@unlink($p);}
                    $session['ok']=false;$session['message']='Critical postflight failed; rollback attempted.';$session['automatic_rollback']=$restore;
                    $_SESSION['mrpi_last']=$session;$_SESSION['mrpi_post']=mrpi_postcheck($session);$message=$session['message'];$messageClass='bad';
                } else {
                    $session['message']='PASS — Payouts first pass installed and passed postflight.';$_SESSION['mrpi_last']=$session;$_SESSION['mrpi_post']=mrpi_postcheck($session);$message=$session['message'];$messageClass='ok';
                }
            } catch(Throwable $e){
                $restore=mrpi_restore_backup($backup);foreach($created as $p)if(is_file($p))@unlink($p);
                $session=['last_action'=>'apply','at_et'=>date('c'),'ok'=>false,'message'=>'Apply failed: '.$e->getMessage(),'backup'=>$backup,'created_files'=>$created,'automatic_rollback'=>$restore];
                $_SESSION['mrpi_last']=$session;$_SESSION['mrpi_post']=mrpi_postcheck($session);$message=$session['message'];$messageClass='bad';
            }
        }
    } elseif ($action==='rollback') {
        $last=$_SESSION['mrpi_last']??[];$restore=mrpi_restore_backup((array)($last['backup']??[]));
        foreach((array)($last['created_files']??[]) as $p){if(is_file((string)$p))@unlink((string)$p);}
        $session=['last_action'=>'rollback','at_et'=>date('c'),'ok'=>!empty($restore['ok']),'message'=>!empty($restore['ok'])?'Rollback complete.':'Rollback completed with one or more restore failures.','backup'=>$last['backup']??[],'created_files'=>$last['created_files']??[],'automatic_rollback'=>null];
        $_SESSION['mrpi_last']=$session;$_SESSION['mrpi_post']=mrpi_postcheck($session);$message=$session['message'];$messageClass=$session['ok']?'ok':'bad';
    }
}

$pre=mrpi_preflight();$post=$_SESSION['mrpi_post']??null;
$preJson=json_encode($pre,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
$postJson=is_array($post)?json_encode($post,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE):'';
if(isset($_GET['download'])&&in_array($_GET['download'],['pre','post'],true)){
    $which=(string)$_GET['download'];$payload=$which==='post'?$postJson:$preJson;if($payload==='')$payload="{\n  \"status\": \"No postcheck available yet\"\n}";
    $stage=$which==='post'?'POSTCHECK':'PRECHECK';$fn='install_payouts_first_pass_v001_'.date('Ymd_His').'_'.$stage.'.json';header('Content-Type: application/json; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$fn.'"');echo $payload.PHP_EOL;exit;
}
?>
