</div><script>function copyReport(id,btn){var el=document.getElementById(id);if(!el)return;var txt=el.value;function done(){var old=btn.textContent;btn.textContent='Copied!';setTimeout(function(){btn.textContent=old;},1200);}if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(txt).then(done).catch(function(){el.focus();el.select();document.execCommand('copy');done();});}else{el.focus();el.select();document.execCommand('copy');done();}}</script></body></html>
